impl Locale {
    #[must_use]
    pub fn code(self) -> &'static str {
        match self {
            Self::EnUs => "en-US",
            Self::DeDe => "de-DE",
            Self::FrFr => "fr-FR",
            Self::EsEs => "es-ES",
            Self::JaJp => "ja-JP",
            Self::Ar => "ar",
            Self::EnXa => "en-XA",
            Self::ArXb => "ar-XB",
            Self::JaXc => "ja-XC",
        }
    }

    #[must_use]
    pub fn direction(self) -> &'static str {
        match self {
            Self::EnUs => "ltr",
            Self::DeDe => "ltr",
            Self::FrFr => "ltr",
            Self::EsEs => "ltr",
            Self::JaJp => "ltr",
            Self::Ar => "rtl",
            Self::EnXa => "ltr",
            Self::ArXb => "rtl",
            Self::JaXc => "ltr",
        }
    }

    #[must_use]
    pub fn script(self) -> &'static str {
        match self {
            Self::EnUs => "latn",
            Self::DeDe => "latn",
            Self::FrFr => "latn",
            Self::EsEs => "latn",
            Self::JaJp => "jpan",
            Self::Ar => "arab",
            Self::EnXa => "latn",
            Self::ArXb => "arab",
            Self::JaXc => "jpan",
        }
    }

    #[must_use]
    pub fn parse_tag(raw: &str) -> Option<Self> {
        match raw.trim().to_ascii_lowercase().as_str() {
            "en" | "en-us" | "c" | "posix" => Some(Self::EnUs),
            "de" | "de-de" => Some(Self::DeDe),
            "fr" | "fr-fr" => Some(Self::FrFr),
            "es" | "es-es" => Some(Self::EsEs),
            "ja" | "ja-jp" => Some(Self::JaJp),
            "ar" | "ar-sa" | "ar-ae" | "ar-eg" => Some(Self::Ar),
            "en-xa" => Some(Self::EnXa),
            "ar-xb" => Some(Self::ArXb),
            "ja-xc" => Some(Self::JaXc),
            _ => None,
        }
    }
}

